local wall = 0function onEvent(tag)if tag == 'change' thenwall = wall + 1if wall == 1 thensetProperty('idkbackground3.alpha', 0);setProperty('idkbackground4.alpha', 1);setProperty('idkbackground5.alpha', 0);elseif wall == 2 thensetProperty('idkbackground3.alpha', 1);setProperty('idkbackground4.alpha', 0);setProperty('idkbackground5.alpha', 0);elseif wall == 3 thensetProperty('idkbackground3.alpha', 0);setProperty('idkbackground4.alpha', 1);setProperty('idkbackground5.alpha', 0);elseif wall == 4 thensetProperty('idkbackground3.alpha', 0);setProperty('idkbackground4.alpha', 0);setProperty('idkbackground5.alpha', 1);elseif wall == 5 thenwall = 0endendend